[
  {
    "statement": "Studies evaluating artificial roosts for bats have documented several benefits.",
    "citations": []
  },
  {
    "statement": "Bat boxes show positive uptake.",
    "citations": []
  },
  {
    "statement": "Nine studies in Europe and the USA found that the number of bats using bat boxes increased by 2-10 times up to 10 years after installation.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Forty-one of 43 studies found that bats used bat boxes installed in various habitats including forests, woodlands, farmland, wetlands, and urban areas.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Seventy-two bat species have been documented using bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Only 18 bat species commonly used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Thirty-one bat species used bat boxes as maternity roosts.",
    "citations": [
      "1024"
    ]
  },
